const http = require('http');
const fs = require('fs');

const server = http.createServer((req, res) => {
  if (req.url === '/api/design-review' && req.method === 'POST') {
    let body = '';
    req.on('data', chunk => body += chunk.toString());
    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        console.log('Received registration:', JSON.stringify(data, null, 2));
        // Store registration
        fs.writeFileSync('registration.json', body);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'registered', sessionId: 'sess-123' }));
      } catch (err) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('Not Found');
  }
});

const PORT = 3003;
server.listen(PORT, () => {
  console.log(`Mock design review server running on http://localhost:${PORT}`);
});

